    girl_patches = image_patch.find("girl")

    if not bike_patches or not girl_patches:
        return image_patch

    bike_centers = [(p.left + p.right) / 2 for p in bike_patches]
    girl_centers = [(p.left + p.right) / 2 for p in girl_patches]

    for bike_center in bike_centers:
        for girl_center in girl_centers:
            if abs(bike_center - girl_center) < 50:  # Assuming a threshold of 50 pixels for being "on"
                return image_patch

    return image_patch

